/**
 * Notion API Client
 * Hybrid approach: Tries cached data first, falls back to API if needed
 */

import type { Sprint } from '@/data/projects';

/**
 * Notion API Base URL
 * Points to the backend server that handles Notion API calls
 */
const NOTION_API_BASE = 'https://jagdnotionapiserver.vercel.app/api/notion';

// Cache for static roadmap data
let roadmapsCache: Record<string, Sprint[]> | null = null;
let cacheAttempted = false;

/**
 * Try to load from static cache (generated by sync script)
 */
async function tryLoadCache(): Promise<Record<string, Sprint[]>> {
  if (!cacheAttempted) {
    cacheAttempted = true;
    try {
      // Use dynamic import with template to prevent Vite static analysis
      const modulePath = `@/data/${'roadmaps'}`;
      const module = await import(/* @vite-ignore */ modulePath);
      roadmapsCache = module.roadmaps as Record<string, Sprint[]>;
      if (import.meta.env.DEV) {
        console.log(`✅ Loaded cached roadmaps for ${Object.keys(roadmapsCache).length} projects`);
      }
    } catch {
      if (import.meta.env.DEV) {
        console.log('ℹ️  No cached roadmaps found, will use API fallback');
      }
    }
  }
  return roadmapsCache || {};
}

/**
 * Fetch roadmap data for all projects
 * Tries cache first, falls back to API
 * @returns Object mapping project slugs to their roadmap sprints
 */
export async function fetchAllRoadmaps(): Promise<Record<string, Sprint[]>> {
  // Try cache first
  const cache = await tryLoadCache();
  if (Object.keys(cache).length > 0) {
    if (import.meta.env.DEV) {
      console.log(`📦 Using cached roadmaps`);
    }
    return cache;
  }

  // Fallback to API
  try {
    if (import.meta.env.DEV) {
      console.log(`📡 Fetching all roadmaps from API...`);
    }
    const response = await fetch(`${NOTION_API_BASE}/sprints`);
    const result = await response.json();
    
    if (!result.success) {
      throw new Error(result.error || 'Failed to fetch roadmap');
    }
    
    return result.data;
  } catch (error: unknown) {
    if (import.meta.env.DEV) {
      console.error('Error fetching Notion roadmap:', error);
    }
    return {};
  }
}

/**
 * Validate project slug format
 * @param slug - Project slug to validate
 * @returns true if valid, false otherwise
 */
function isValidProjectSlug(slug: string): boolean {
  // Allow alphanumeric, hyphens, and underscores only
  const validSlugPattern = /^[a-zA-Z0-9_-]+$/;
  return validSlugPattern.test(slug) && slug.length > 0 && slug.length <= 100;
}

/**
 * Fetch roadmap sprints for a specific project by slug
 * Tries cache first, falls back to API
 * @param projectSlug - The project slug to filter by (e.g., 'scholarlens-ai')
 * @returns Array of Sprint objects for the project
 */
export async function fetchProjectRoadmap(projectSlug: string): Promise<Sprint[]> {
  // Input validation
  if (!projectSlug || typeof projectSlug !== 'string') {
    if (import.meta.env.DEV) {
      console.warn('⚠️  Invalid project slug: must be a non-empty string');
    }
    return [];
  }

  if (!isValidProjectSlug(projectSlug)) {
    if (import.meta.env.DEV) {
      console.warn('⚠️  Invalid project slug format:', projectSlug);
    }
    return [];
  }

  // Try cache first
  const cache = await tryLoadCache();
  if (cache[projectSlug]) {
    if (import.meta.env.DEV) {
      console.log(`📦 Using cached roadmap for ${projectSlug}`);
    }
    return cache[projectSlug];
  }

  // Fallback to API
  try {
    const url = `${NOTION_API_BASE}/sprints?projectSlug=${encodeURIComponent(projectSlug)}`;
    if (import.meta.env.DEV) {
      console.log(`📡 Fetching roadmap from API: ${url}`);
    }
    
    const response = await fetch(url);
    
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    
    const result = await response.json();
    
    if (!result.success) {
      throw new Error(result.error || 'Failed to fetch project roadmap');
    }

    const roadmapData: Sprint[] = Array.isArray(result.data) ? result.data : [];
    
    if (import.meta.env.DEV) {
      console.log(`✅ Received ${roadmapData.length} sprints for ${projectSlug}`);
    }
    
    return roadmapData;
  } catch (error: unknown) {
    if (import.meta.env.DEV) {
      console.error(`❌ Error fetching roadmap for project ${projectSlug}:`, error);
    }
    return [];
  }
}
